const rows=[];
// Each option list starts with the correct answer. Sessions shuffle it independently.
function add(c,id,title,q,a,why,flags='',source=`c${c}`,ref=''){
  rows.push({id,c,title,q,a,why,p:flags.includes('p'),k:flags.includes('k'),f:flags.includes('f'),source,ref,front:q,back:`${a[0]}. ${why}`});
}
add(1,'diversity','Indigenous Americas','Which describes the Americas before European arrival?', ['Many societies with distinct languages, economies and governments','One nation with one language','An uninhabited continent','Only nomadic societies without farming'],'Cities, farming communities and mobile societies existed side by side. Indigenous history did not begin with European contact.','','supplemental');
add(1,'maize','Maize','Why was maize important in many American societies?', ['It supported agriculture and larger settled communities','It first arrived from England in 1607','It eliminated regional differences','It was used only as currency'],'Agriculture helped sustain settlements, but different environments produced different ways of life.','k','supplemental');
add(1,'feudal','Feudalism','Which relationship was central to European feudalism?', ['Landholding and obligations between lords and dependents','Universal voting for national presidents','Factory wages and labor unions','Overseas trade controlled by elected colonial assemblies'],'Medieval society linked land, status and service. Later commercial growth changed these relationships.','k','supplemental');
add(1,'reformation','Protestant Reformation','What did the Protestant Reformation challenge?', ['The authority and practices of the Roman Catholic Church','The existence of every form of Christianity','The Articles of Confederation','The Louisiana Purchase'],'Religious divisions shaped European politics and later colonial settlement.','k','supplemental');
add(1,'westafrica','West African states','Which claim about precolonial West Africa is accurate?', ['It included powerful states and extensive trade networks','It had no governments or long-distance trade','All communities shared one culture','European traders created all African institutions'],'Ghana, Mali and Songhai belonged to long histories of state formation and exchange.','','supplemental');
add(1,'slavery-atlantic','Atlantic slavery','How did the Atlantic slave trade transform slavery?', ['It expanded forced migration and hereditary racial slavery in the Americas','It made enslaved labor voluntary','It began only after the US Constitution','It ended plantation labor'],'European plantation economies drove an expanding trade in enslaved Africans. Older forms of bondage were not all identical to this system.','','supplemental');
add(2,'tordesillas','Treaty of Tordesillas','What did Spain and Portugal attempt in the Treaty of Tordesillas (1494)?', ['Divide overseas claims along a line in the Atlantic','Recognize US independence','Establish religious freedom in Maryland','End the War of 1812'],'Portugal claimed lands east of the line and Spain west of it. Indigenous peoples did not consent to this division.','pf','supplemental');
add(2,'lascasas','Bartolomé de Las Casas','Why is Bartolomé de Las Casas important?', ['He condemned Spanish abuses against Indigenous people','He negotiated the US Constitution','He commanded the British at Quebec','He founded the Sons of Liberty'],'The Dominican friar argued against conquest abuses and Indigenous enslavement. His position on African slavery also changed over his lifetime.','pf','lascasas');
add(2,'exchange','Columbian Exchange','Which is an example of the Columbian Exchange?', ['Movement of crops, animals and diseases between hemispheres','A compromise over Senate representation','A tax on printed colonial papers','The sale of Louisiana in 1803'],'Exchange changed diets and environments; epidemic diseases devastated many Indigenous communities.','k','supplemental');
add(2,'encomienda','Encomienda','What did the encomienda system authorize?', ['Spanish claims to Indigenous labor and tribute','An elected Indigenous seat in Parliament','Universal religious tolerance','A ban on all forced labor'],'Colonizers claimed obligations of protection and conversion while extracting labor and tribute.','k','supplemental');
add(2,'middlepassage','Middle Passage','What was the Middle Passage?', ['The forced Atlantic voyage of enslaved Africans to the Americas','A route across the Appalachian Mountains','A canal built after the Revolution','The boundary in the Treaty of Paris'],'People endured confinement, violence, disease and high mortality during the crossing.','k','supplemental');
add(2,'mercantilism','Mercantilism','What was the central colonial aim of mercantilism?', ['Enrich and strengthen the home country through controlled trade','Allow every colony independent foreign policy','End customs duties permanently','Replace colonies with equal sovereign states'],'Colonies supplied raw materials and markets within an imperial trading system.','k','supplemental');
add(3,'roger','Roger Williams','Why did Roger Williams establish Providence in 1636?', ['To create a refuge for religious dissent after banishment from Massachusetts','To build a national bank','To enforce Puritan religious conformity everywhere','To punish the Boston Tea Party'],'He defended liberty of conscience and separation of religious and civil authority.','pf','roger');
add(3,'orders','Fundamental Orders of Connecticut','What did the Fundamental Orders of Connecticut (1639) do?', ['Set a written framework for colonial government','Create the first ten US amendments','Grant complete equality to everyone in the colony','Place Connecticut under French rule'],'They provided institutions and elections for the Connecticut towns; participation still had colonial limits.','pf','supplemental');
add(3,'toleration','Maryland Toleration Act','What is the key limitation of Maryland’s 1649 Toleration Act?', ['Its protection centered on Christians who accepted the Trinity','It protected only atheists','It abolished every religious penalty','It guaranteed modern religious freedom to all people'],'Catholics and Protestants received protection within that boundary. The act also imposed harsh penalties for denying core Christian doctrines.','pf','maryland');
add(3,'burgesses','House of Burgesses','Why is Virginia’s House of Burgesses significant?', ['It established elected colonial representation beginning in 1619','It made Virginia independent from Britain in 1619','It gave every resident the vote','It created the Supreme Court'],'The early representative assembly was part of colonial government under imperial authority, with a limited electorate.','pf','supplemental');
add(3,'jamestown','Jamestown','Which crop helped make Virginia’s colonial economy profitable?', ['Tobacco','Cotton from industrial mills','Tea grown in Boston','Sugar grown across New England'],'Tobacco exports encouraged land expansion and demand for labor in the Chesapeake.','','supplemental');
add(3,'indenture','Indentured servants','How did indentured servitude usually work?', ['Labor for a contracted period in exchange for passage or other support','Guaranteed lifelong hereditary enslavement for every servant','Employment without any contract','Immediate ownership of an entire colony'],'Servants faced harsh conditions. A time-limited contract distinguished the institution from hereditary racial slavery.','k','supplemental');
add(3,'mayflower','Mayflower Compact','What was the purpose of the Mayflower Compact?', ['An agreement to form and obey a civil government at Plymouth','A declaration of independence from every European state','A federal constitution for thirteen states','A treaty ending King Philip’s War'],'The settlers agreed to make and follow laws for their community.','','supplemental');
add(3,'puritan','Puritans','What did Puritans seek?', ['Reform of the Church of England and a godly community','Abolition of all Christian worship','Support for Catholic rule in Massachusetts','Creation of the Democratic-Republican Party'],'Massachusetts Bay enforced religious conformity; dissenters could face expulsion.','k','supplemental');
add(4,'philip','King Philip’s War','What was a central cause of King Philip’s War?', ['Colonial expansion and deteriorating relations over Indigenous land and authority','The Stamp Act of 1765','French support for US independence','The national bank debate'],'Metacom was the Wampanoag leader called King Philip by English colonists. The war devastated communities and weakened Indigenous power in southern New England.','pf','c4');
add(4,'hobbes','A Hobbesian government','Which government best fits Hobbes’s argument in Leviathan?', ['A powerful sovereign able to restrain conflict and maintain security','A government whose defining duty is allowing constant revolution','A system with no common authority','A government based only on free overseas trade'],'Hobbes feared insecurity without common power. His sovereign could be one person or an assembly; the argument is broader than simply “a king.”','pf','hobbes');
add(4,'locke','A Lockean government','Which statement best fits Locke’s theory?', ['Government rests on consent and should protect natural rights','People have no rights before government grants them','Rulers may destroy property without losing legitimacy','Absolute hereditary power is the only lawful authority'],'Life, liberty and property are central. When government violates its trust, people can replace it.','pf','locke');
add(4,'bacon','Legacy of Bacon’s Rebellion','Which long-term development followed Bacon’s Rebellion?', ['Elites increasingly relied on racial slavery and sought to divide laborers','Virginia immediately abolished slavery','Britain granted independence to Virginia','Colonial land conflicts disappeared'],'The 1676 uprising exposed class and frontier tensions. The transition to racial slavery had several causes and was not caused by one event alone.','p','c4');
add(4,'penn','Pennsylvania','What distinguished William Penn’s Pennsylvania?', ['Quaker influence and comparatively broad religious toleration','A compulsory Puritan church','A ban on all Atlantic commerce','A colony founded to enforce the Stamp Act'],'Penn received the proprietary grant in 1681. Tolerance coexisted with inequality and participation in slavery.','p','c4');
add(4,'englishrights','English Bill of Rights (1689)','What did the English Bill of Rights strengthen?', ['Parliament’s authority and limits on royal power','The king’s right to tax without Parliament','American independence','Universal voting in all colonies'],'The Glorious Revolution established a constitutional settlement that constrained the monarch.','p','c4');
add(4,'neglect','Salutary neglect','What was salutary neglect?', ['Relatively lax British enforcement of colonial trade regulations','A total repeal of the Navigation Acts','Colonial independence before 1763','A prohibition on colonial assemblies'],'Loose enforcement encouraged colonial trade and habits of local self-government.','pk','c4');
add(4,'albany','Albany Plan (1754)','What did the Albany Plan propose?', ['A coordinated colonial union for defense and related affairs','A declaration of war on the United States','A bicameral US Congress in 1787','A permanent French government in Virginia'],'Franklin promoted intercolonial cooperation during the imperial conflict. The colonies did not adopt the plan.','p','c4');
add(4,'pitt','William Pitt','How did William Pitt help change the French and Indian War?', ['He increased British resources and support for fighting in North America','He removed all British troops from North America','He allied Britain with the United States in 1754','He negotiated the Louisiana Purchase'],'Greater military investment helped Britain overcome earlier setbacks.','p','c4');
add(4,'quebec1759','Quebec (1759)','Why was Britain’s victory at Quebec significant?', ['It severely weakened French power in Canada','It established US independence immediately','It caused the Boston Massacre','It ended every Indigenous claim to land'],'British forces defeated the French on the Plains of Abraham. The 1763 peace formalized Britain’s major territorial gains.','p','c4');
add(4,'debt1763','The empire after 1763','What made British victory a source of later conflict?', ['An enlarged empire and war debt encouraged tighter control and colonial revenue measures','Victory removed all British debts','Britain surrendered Canada to the US','Colonists unanimously wanted stricter trade enforcement'],'The French and Indian War changed the imperial balance and helped produce the taxation crisis.','p','c4');
add(5,'stamp','Stamp Act','Why did the Stamp Act (1765) provoke resistance?', ['It imposed a direct tax on printed materials without colonial representation in Parliament','It taxed only French ships','It granted colonial voting seats in Parliament','It immediately banned tea'],'Stamped paper was required for legal documents, newspapers and other printed items. Opposition linked taxation to political rights.','pf','c5');
add(5,'quebecact','Quebec Act','Why did Patriots include the Quebec Act in the Intolerable Acts?', ['They resented its territorial expansion and protections for Catholic practice','It closed Boston’s port as a tea punishment','It established elected Patriot government in Quebec','It abolished the British Empire'],'The 1774 Quebec Act expanded Quebec into the Ohio region. It was separate from the four Coercive Acts.','pf','c5');
add(5,'massacre','Boston Massacre','What happened in the Boston Massacre (March 5, 1770)?', ['British soldiers fired during a confrontation and five people died','Patriots captured Fort McHenry','Congress declared independence','The British burned Washington'],'Crispus Attucks was among those killed. Accounts and propaganda shaped how the event was remembered.','k','c5');
add(5,'coercive','Coercive Acts','What were the Coercive Acts intended to do?', ['Punish Massachusetts after the destruction of tea','Reward Massachusetts with independence','Repeal every colonial tax','End the French and Indian War'],'The four acts concerned Boston’s port, Massachusetts government, administration of justice and quartering.','k','c5');
add(5,'intolerable','Intolerable Acts','Which grouping did Patriots call the Intolerable Acts?', ['The Coercive Acts plus the Quebec Act','Only the Stamp Act','The first ten constitutional amendments','Only the Navigation Acts'],'Keep the Patriot label distinct from the four punitive Coercive Acts.','k','c5');
add(5,'correspondence','Committees of Correspondence','What did Committees of Correspondence help organize?', ['Communication and coordinated resistance between colonial communities','British customs enforcement alone','A permanent federal army in 1760','French taxation in Virginia'],'These unofficial bodies helped develop an alternative political network.','k','c5');
add(5,'daughters','Daughters of Liberty','How did the Daughters of Liberty support resistance?', ['Boycotts and production of domestic substitutes for British goods','Collecting the Stamp Act tax','Enforcing the Quebec Act','Negotiating the Treaty of Ghent'],'Homespun clothing and non-importation made household production part of political resistance.','k','c5');
add(5,'direct','Direct tax','Which example is a direct tax in the colonial crisis?', ['The Stamp Act charge paid for stamped documents','A customs duty imposed on imported goods through merchants','The cost of transporting tea','The price of making homespun cloth'],'A direct tax is paid directly by the consumer; an indirect tax is imposed through businesses and prices.','k','c5');
add(5,'indirect','Indirect tax','Which is an indirect tax?', ['A duty imposed on imported goods through merchants','A fee paid directly for a stamped newspaper','A voluntary donation to Congress','A tax-free barter exchange'],'Consumers can still bear the cost through higher prices. The collection method differs from a direct tax.','k','c5');
add(5,'loyalists','Loyalists','Who were Loyalists?', ['Colonists who remained loyal to Great Britain','Everyone living in Boston','Only French officers in the Continental Army','Members of the First Continental Congress by definition'],'People’s allegiances varied; independence did not have unanimous colonial support.','k','c5');
add(5,'circular','Massachusetts Circular','What did Samuel Adams’s Massachusetts Circular encourage?', ['Opposition to taxation without representation and coordinated boycotts','Acceptance of every parliamentary tax','Immediate ratification of the Constitution','Support for the Louisiana Purchase'],'The letter sought cooperation among colonial legislatures.','k','c5');
add(5,'representation','No taxation without representation','What did this principle challenge?', ['Parliament’s taxation of colonists who lacked their own representatives there','Any tax approved by a colonial assembly','The existence of every elected government','All trade with other colonies'],'Patriots challenged Parliament’s claim of virtual representation; they did not reject taxation in every circumstance.','k','c5');
add(5,'nonimport','Non-importation movement','What is a non-importation movement?', ['A boycott of imported goods','A ban on all colonial communication','A tax on newspapers','A permanent military alliance'],'Colonists used collective purchasing decisions to pressure British merchants and government.','k','c5');
add(5,'proclamation','Proclamation Line','What did the Proclamation of 1763 restrict?', ['Colonial settlement west of a line along the Appalachians','British settlement in London','Atlantic fishing off Newfoundland','Voting in every colonial assembly'],'Britain sought to manage frontier conflict. Colonists seeking western land resented the restriction.','k','c5');
add(5,'sons','Sons of Liberty','Which description fits the Sons of Liberty?', ['Artisans, shopkeepers and merchants who resisted the Stamp Act','British royal judges without juries','French soldiers who defended Quebec','A national political party founded in 1800'],'They saw themselves as defenders of British liberties during the imperial crisis.','k','c5');
add(5,'suffolk','Suffolk Resolves','What did the Suffolk Resolves recommend?', ['Resistance to the Intolerable Acts, militia preparation and coordinated economic boycotts','Disbanding colonial militias','Acceptance of Boston’s port closure','Immediate restoration of the tea to Britain'],'Their resistance program influenced the First Continental Congress.','k','c5');
add(5,'admiralty','Vice-admiralty courts','What troubled colonists about vice-admiralty courts?', ['They tried maritime and customs cases without juries','They allowed every colonist a seat in Parliament','They refused to enforce customs laws','They were elected Patriot assemblies'],'The lack of a jury became part of the argument about threatened English liberties.','k','c5');
add(6,'historiography','Historiography of the Revolution','What does historiography ask you to examine?', ['How historians interpret evidence and explain the Revolution differently','Only the exact dates of battles','Which fictional game character won the war','Whether all accounts agree automatically'],'Political ideas, economic interests and social experiences can produce different interpretations. The outline names historiography, but the corresponding lecture was not supplied.','pf','notes');
add(6,'washington','George Washington','Why was Washington’s leadership important to independence?', ['He helped keep an army and the cause alive through setbacks','He won every battle without foreign aid','He wrote Common Sense','He commanded the British fleet'],'Preserving the Continental Army, coordinating allies and maintaining commitment mattered alongside individual victories.','pf','c6');
add(6,'paris1783','Treaty of Paris (1783)','What did the Treaty of Paris (1783) formally establish?', ['British recognition of US independence and national boundaries','The sale of Louisiana','Peace after the War of 1812','A universal grant of land rights to Indigenous peoples'],'The Mississippi formed the western boundary of US claims. Native nations were excluded from the negotiations.','pf','c6');
add(6,'saratoga','Saratoga','Why was Saratoga a turning point?', ['It helped persuade France to formally ally with the United States','It immediately ended the war in 1777','It gave Britain control of every colony','It began the Stamp Act crisis'],'French entry in 1778 brought vital money, troops and naval power.','','c6');
add(6,'yorktown','Yorktown','Why did Cornwallis surrender at Yorktown?', ['French and American armies besieged him while French naval forces blocked relief','Washington defeated him without any allies','Congress abolished the British army by vote','The Treaty of Ghent required surrender'],'The 1781 victory accelerated peace negotiations; the formal peace followed in 1783.','','c6');
add(6,'revolution-limits','Limits of revolutionary liberty','Which best describes the Revolution’s social legacy?', ['Expanded political possibilities while slavery and many exclusions persisted','Immediate equality in voting and freedom for everyone','No change in political ideas','Universal agreement among Native nations and colonists'],'Women, enslaved people and Native nations experienced the war and its aftermath differently.','','c6');
add(7,'republic','Republican government','What defines a republic in this chapter?', ['Government without a hereditary monarch, grounded in public authority','Direct voting on every decision by every resident','A permanent hereditary aristocracy','Rule by an unelected king'],'A republic can have elected representatives while still restricting who may vote.','f','c7','P006–013');
add(7,'democracy','Democracy','What worried conservative Whigs about democracy?', ['Majority rule could threaten property and established order','Only kings could vote','There could be no elected institutions','Democracy required British control'],'Radical Whigs favored wider participation. Neither camp necessarily supported universal equality.','kf','c7','P009–010');
add(7,'whigs','Conservative & radical Whigs','Which contrast best describes these Whig groups?', ['Conservatives favored elite leadership; radicals favored wider participation','Both demanded a British monarch','Radicals demanded hereditary aristocracy','Conservatives supported universal voting immediately'],'Both could support republicanism while disagreeing about who should hold power.','kf','c7','P009–013');
add(7,'abigail','Abigail Adams','What did Abigail Adams ask John Adams to consider in 1776?', ['Women’s interests and protection in the new legal order','A return to monarchy','The Louisiana Purchase','A national bank monopoly'],'Her appeal exposed the gap between revolutionary liberty and women’s political and legal position.','pf','notes','IMG_5801');
add(7,'warren','Mercy Otis Warren','What did Mercy Otis Warren contribute to revolutionary politics?', ['Political writing and criticism of the proposed Constitution’s concentration of power','Command of the French navy','Authorship of the Stamp Act','A defense of absolute monarchy'],'Her 1788 Observations opposed the Constitution. Her History of the American Revolution appeared in 1805, not 1812.','pf','notes','IMG_5801; C7P018');
add(7,'motherhood','Republican motherhood','What did republican motherhood emphasize?', ['Women educating children to become virtuous citizens','Equal voting rights for every woman in 1776','Women serving as hereditary rulers','Excluding women from every form of education'],'It elevated a civic role in the household while leaving women outside most formal political power.','f','c7','P015–020');
add(7,'coverture','Coverture','What did coverture do to a married woman’s legal identity?', ['Subordinated it to her husband’s legal identity','Guaranteed her a vote in every state','Automatically freed everyone she enslaved','Made her a member of Congress'],'The doctrine restricted independent property and legal action; practice varied by jurisdiction.','kf','c7','P016');
add(7,'murray','Judith Sargent Murray','What argument did Judith Sargent Murray make?', ['Women’s apparent disadvantages came from unequal education, not inferior intellect','Women should never learn to read','Republican government required a queen','Only men could have moral judgment'],'Her writing challenged assumptions about women’s capabilities.','','c7','P019');
add(7,'rejected','What the Revolution rejected','Which institutions did revolutionary republicanism reject?', ['Hereditary monarchy and aristocratic political privilege','Every elected assembly','All private property','All religious belief'],'The new nation rejected hereditary rulers without removing all social hierarchies.','pf','notes','IMG_5801');
add(7,'voting','Voting after independence','How did voting change after independence?', ['Participation broadened for some men, while major exclusions remained','Every adult immediately gained equal voting rights','Every state abolished all property requirements at once','Only British officials could vote'],'State rules differed. Race, sex, property and other qualifications still limited citizenship in practice.','pf','notes','IMG_5801–5802');
add(7,'religion','Freedom of religion','What was an important revolutionary-era religious change?', ['Challenges to established churches and movement toward religious liberty','A national compulsory Puritan church','A permanent prohibition on Catholic worship everywhere','An immediate end to every state religious establishment'],'Virginia’s 1786 statute is a major example. Change was uneven; some establishments lasted longer.','pf','notes','IMG_5802; C7P030–032');
add(7,'freetrade','Free trade & Adam Smith','What was Adam Smith’s free-trade argument?', ['Self-interest and competition could guide economic activity without mercantilist controls','Every price should be set by a king','Colonies should trade only through one imperial monopoly','Markets guarantee equal wealth to everyone'],'The Wealth of Nations appeared in 1776. The “invisible hand” describes coordination, not a promise that every market outcome is fair.','pf','notes','IMG_5802');
add(7,'nativeparis','Treaty of Paris & Native nations','What did the Treaty of Paris mean for Native nations?', ['Britain transferred territorial claims without obtaining Native consent','Native nations unanimously ceded all their lands','It protected every Native boundary permanently','It ended all Indigenous governments'],'US claims expanded across lands inhabited and governed by Native peoples. Treating them as empty land misstates the history.','pf','notes','IMG_5802; C7P027–029');
add(7,'manumission','Manumission','What is manumission?', ['An enslaver’s legal freeing of an enslaved person','The automatic abolition of slavery everywhere','The creation of a royal monopoly','The election of a senator'],'Individual manumissions and gradual abolition expanded in some places; slavery persisted elsewhere.','kf','c7','P025');
add(7,'abolition','Slavery after the Revolution','Which describes emancipation after the Revolution?', ['Some northern states adopted gradual abolition while southern slavery endured','All thirteen states abolished slavery in 1783','The Constitution freed every enslaved person','No one challenged slavery anywhere'],'Freedom developed unevenly. Claims of equality coexisted with enslavement and racial exclusion.','f','c7','P021–026');
add(7,'states','State constitutions','Which contrast between state constitutions is accurate?', ['Pennsylvania’s 1776 legislature had one house; Massachusetts’s 1780 system included a stronger governor','Every state used exactly the same institutions','Pennsylvania kept a hereditary king','Massachusetts abolished property qualifications entirely'],'Pennsylvania also had an executive council. “No governor” does not mean it had no executive institution.','f','c7','P036–044');
add(7,'unicameral','Unicameral','What is a unicameral legislature?', ['A legislature with one chamber','A legislature with two chambers','Three executive departments','A court without a jury'],'The Confederation Congress was unicameral.','kf','c7','P036, P045');
add(7,'bicameral','Bicameral','What is a bicameral legislature?', ['A legislature with two chambers','A legislature with one chamber','A government without courts','A monarchy with two kings'],'The US Congress has a House and a Senate.','kf','c7','P060');
add(7,'articles','Articles of Confederation','Which design belonged to the Articles?', ['One vote per state in Congress and strong state autonomy','A directly elected national president','Equal population-based votes for each individual voter','A national Supreme Court like today’s'],'Adopted in 1777 and fully ratified in 1781, the Articles established a confederation.','pf','notes','IMG_5803–5804');
add(7,'articlespowers','The Confederation’s powers','Which was a major financial limitation under the Articles?', ['Congress depended on state contributions rather than directly taxing individuals','Congress could not borrow any money','Congress could not emit any bills of credit','Congress could not conduct diplomacy'],'Congress could borrow and issue bills of credit. The central problem was inadequate independent revenue and enforcement.','pf','articles','Article VIII–IX');
add(7,'amendments','Changing the Articles','How many states had to agree to amend the Articles?', ['All thirteen','Nine','A simple majority of seven','Only the largest state'],'Unanimity made structural changes difficult. Nine states were needed for specified major congressional measures, not every ordinary decision.','pf','articles','Article IX, XIII');
add(7,'courtsexec','Articles: courts & executive','What institutional weakness did reformers identify?', ['No separate national executive or general national court system like the Constitution’s','No state governments at all','A president with unlimited power','A Supreme Court that could directly tax citizens'],'There were limited special tribunals and procedures under the Articles. The missing institutions were a general national judiciary and independent executive.','pf','notes','IMG_5804');
add(7,'northwest','Northwest Ordinance (1787)','What did the Northwest Ordinance establish?', ['A process toward equal statehood and a slavery prohibition in the Northwest Territory','Permanent colonial status for all western territories','A ban on slavery throughout all thirteen states','A right for Britain to govern Ohio'],'It organized the region north of the Ohio River. Expansion still threatened Native lands and sovereignty.','pf','notes','IMG_5804; C7P049–050');
add(7,'land1785','Land Ordinance (1785)','How did the Land Ordinance organize surveys?', ['Square townships six miles on each side','Townships of only six square miles','States with identical population','Congressional districts based on enslaved populations'],'Six miles by six miles makes 36 square miles. The grid supported land sales and settlement.','','c7','P048');
add(7,'marylandholdout','Maryland’s holdout','Why did Maryland delay ratifying the Articles?', ['Concern about other states’ western land claims','It wanted to join France','It insisted on a national bank in 1777','It opposed every form of union'],'Promises of western land cessions helped resolve the dispute; final ratification came in 1781.','','notes','IMG_5803');
add(7,'shays','Shays’s Rebellion','What drove many participants in Shays’s Rebellion?', ['Debt, taxes, foreclosures and frustration among farmers and veterans','A desire to enforce the Stamp Act','Support for the British invasion of Baltimore','Opposition to religious liberty alone'],'Court closures sought to prevent debt enforcement. In 1787 state forces stopped the attempt to seize the Springfield arsenal.','pf','notes','IMG_5804–5805');
add(7,'shaysviews','Different views of Shays’s Rebellion','Why did elites and rebels interpret the uprising differently?', ['Rebels saw grievances over debt; elites feared disorder and weak national authority','Both sides agreed that every debt should vanish','Rebels were British regulars enforcing taxes','The uprising had nothing to do with government'],'Its defeat and the national government’s weakness strengthened arguments for constitutional reform.','pf','notes','IMG_5805');
add(7,'annapolis','Annapolis Convention','Why was the Annapolis Convention important?', ['Its limited meeting on commerce helped call for a broader convention in 1787','It ratified the Bill of Rights','It ended the War of 1812','It elected Washington president in 1786'],'Only five states attended in 1786. Reformers sought stronger national institutions.','pf','c7','P057');
add(7,'convention','Philadelphia Convention','Which statement about the 1787 Convention is accurate?', ['Delegates moved beyond revising the Articles to frame a new Constitution','All thirteen states sent delegates','Jefferson and John Adams attended throughout','Its debates were broadcast publicly each day'],'Fifty-five delegates from twelve states participated; Rhode Island sent none. Secrecy encouraged debate.','f','c7','P058–059');
add(7,'virginia','Virginia Plan','Which representation principle favored large states?', ['Representation based on population','One equal vote per state in a single chamber','Representation based only on land area','No legislative representation'],'Madison’s ideas, presented by Randolph, proposed a stronger government with three branches and a two-house legislature.','pf','notes','IMG_5805');
add(7,'newjersey','New Jersey Plan','What did the New Jersey Plan defend?', ['Equal state votes in a single-house legislature','Population-based representation in both houses','A hereditary national monarch','An end to all state governments'],'Paterson’s plan appealed to small states afraid of domination by larger states.','pf','notes','IMG_5805');
add(7,'compromise','Connecticut Compromise','How did the Connecticut (Great) Compromise resolve representation?', ['Population in the House; equal state representation in the Senate','Equal seats in both houses regardless of population','Population in the Senate; no House','One king chosen by all state governors'],'Roger Sherman and Oliver Ellsworth helped reconcile large- and small-state demands. Each state received two senators.','pkf','c7','P062; IMG_5806');
add(7,'proportional','Proportional representation','What is proportional representation in this chapter?', ['Allocation of legislative seats according to population','The same number of seats for every state','Appointment of judges for life','A ban on taxation'],'It describes the House’s representation principle, not the Senate’s equal state seats.','kf','c7','P060');
add(7,'threefifths','Three-fifths compromise','What did the three-fifths clause calculate?', ['How enslaved people were counted for representation and direct-tax apportionment','A grant of three-fifths of ordinary civil rights','A limit of three-fifths of states for ratification','A promise to free three-fifths of enslaved people'],'It increased slaveholding states’ political influence without giving the enslaved a vote or freedom.','pkf','constitution','Article I §2; IMG_5806');
add(7,'slavetrade','Constitution & slave trade','What did the Constitution allow Congress to do beginning in 1808?', ['Prohibit the international importation of enslaved people','Automatically abolish slavery inside every state','Award voting rights to every enslaved person','Restore the British slave-trade monopoly'],'The clause prevented Congress from banning the covered importation before 1808. It did not end domestic slavery.','pf','constitution','Article I §9; IMG_5806');
add(7,'federalism','Federalism','What is federalism?', ['Division of authority between national and state governments','Separation of powers only inside Congress','A system with no national government','Government by a hereditary aristocracy'],'Federalism concerns levels of government; separation of powers concerns branches.','pf','notes','IMG_5806');
add(7,'separation','Separation of powers','Which is an example of separation of powers?', ['Legislative, executive and judicial branches have different functions','Every branch exercises all authority alone','States receive equal senators','The national government has no power'],'Dividing functions helps prevent concentrated authority.','pf','notes','IMG_5806');
add(7,'checks','Checks and balances','Which is a check on presidential power?', ['Congress can override a veto with the required supermajorities','The president alone can repeal the Constitution','The Senate cannot review any appointment','Courts must always obey executive preferences'],'Checks allow one branch to restrain another. Madison explained the logic in Federalist No. 51.','pkf','c7','P034; slide 92');
add(7,'sovereignty','Popular sovereignty','What does popular sovereignty mean?', ['Government’s authority ultimately rests with the people','Only a king possesses legitimate power','Every state must have the same population','A government is unlimited once elected'],'Representation and limited government were ways to organize that principle, with important historical exclusions.','pf','notes','IMG_5806');
add(7,'electoral','Electoral College','How is a state’s number of presidential electors determined?', ['Its House seats plus its Senate seats','Exactly two for every state','Only its land area','Only its number of governors'],'The original selection system differed from today’s; the Twelfth Amendment later separated votes for president and vice president.','kf','c7','P067');
add(7,'federalists','Federalists (ratification)','What did Federalists argue during ratification?', ['A stronger national Constitution was needed to preserve the republic','The Articles already provided every needed national power','A British king should rule again','A bill of rights alone should replace every governing institution'],'Washington and Franklin supported ratification. This ratification movement is related to, but not identical with, the later Federalist Party.','pkf','notes','slide 89–90');
add(7,'antifederalists','Anti-Federalists','What was a major Anti-Federalist concern?', ['Central power might threaten liberty, state authority and ordinary citizens','The Constitution guaranteed too many individual rights','States had already been abolished by the Articles','The proposed government was too weak to tax'],'Many demanded an explicit bill of rights. Their objections were varied rather than one identical program.','pkf','notes','slide 94–97');
add(7,'papers','Federalist Papers','Who wrote the Federalist Papers under the name Publius?', ['Hamilton, Madison and Jay','Jefferson, Adams and Washington','Penn, Williams and Las Casas','Jackson, Clay and Calhoun'],'The 1787–1788 essays defended ratification, especially in New York, and explain the proposed government’s design.','pf','notes','slide 91');
add(7,'ratification','Ratification','What was required to put the Constitution into effect under Article VII?', ['Ratification by conventions in nine states','A unanimous vote by all thirteen state legislatures','A majority vote in the British Parliament','Approval by the president before his election'],'State conventions debated adoption. New Hampshire became the ninth ratifying state in June 1788.','pf','constitution','Article VII');
add(7,'billrights','Bill of Rights','What helped resolve demands for explicit rights during ratification?', ['A promise of amendments, followed by the Bill of Rights in 1791','Immediate return to monarchy','Removal of every national power','Ratification by Britain'],'Madison introduced amendments in 1789. The first ten ratified amendments became the Bill of Rights.','pf','notes','slide 97–99');
add(7,'firstamend','First Amendment','Which freedoms are protected by the First Amendment?', ['Religion, speech, press, assembly and petition','A guaranteed government job for every citizen','A right to avoid all taxation','The election of Supreme Court justices'],'It bars laws establishing religion or prohibiting its free exercise and protects these expressive freedoms.','pf','rights','Amendment I; slide 99');
add(7,'fifthamend','Fifth Amendment','Which protection belongs to the Fifth Amendment?', ['Protection against compelled self-incrimination and deprivation without due process','A compulsory religion','Unlimited executive imprisonment','A direct popular vote for president'],'It also addresses grand juries, double jeopardy and compensation for property taken for public use.','pf','rights','Amendment V; slide 99');
add(7,'tenth','Tenth Amendment','Where are powers not delegated to the US or prohibited to states reserved?', ['To the states or the people','Only to the president','Only to Congress','Only to the courts'],'The words “or to the people” matter. The amendment concerns the distribution of undelegated powers.','f','rights','Amendment X');
add(8,'firstpresident','Washington’s presidency','Which precedent did Washington establish by leaving office after two terms?', ['A voluntary limit later followed by many presidents','A constitutional two-term limit already written in 1787','Automatic succession by his eldest son','A ban on future presidential elections'],'He was unanimously chosen by the Electoral College in 1789 and 1792. The legal two-term amendment came much later.','f','notes','slides 2–4, 15, 21');
add(8,'hamilton','Hamilton’s goal','What national future did Hamilton favor?', ['A strong commercial nation with manufacturing, finance and military capacity','A nation with no banks or industry','A return to colonial dependence on France','A federal government with no revenue'],'Britain provided a model of commercial power. Merchants, manufacturers and financiers often backed him.','pf','notes','slides 5–7');
add(8,'assumption','Assumption of state debts','Why did Hamilton propose federal assumption of state war debts?', ['To strengthen national credit and tie creditors to the federal government','To erase every obligation without payment','To give each state an independent foreign policy','To abolish Congress’s power to tax'],'Some states had paid more of their debt already; opponents also objected to speculators profiting.','pf','notes','slides 6, 9; C8P027–031');
add(8,'bank','Bank of the United States','How did Hamilton defend creating a national bank?', ['Implied powers under the Necessary and Proper Clause','An explicit constitutional sentence naming that exact bank','The president’s hereditary rights','A clause forbidding all federal financial institutions'],'The bank supported public finance and commerce. Jefferson and Madison challenged its constitutionality.','pf','notes','slides 6, 10, 12');
add(8,'construction','Strict & loose construction','Which contrast describes the bank debate?', ['Jefferson stressed enumerated powers; Hamilton defended appropriate implied powers','Both agreed the Constitution banned every kind of bank','Hamilton rejected every national power','Jefferson wanted an absolute monarch'],'“Necessary and proper” was central to their different interpretations.','pf','notes','slide 10');
add(8,'compromise1790','Compromise of 1790','What was linked in the Compromise of 1790?', ['Federal assumption of state debt and a permanent capital on the Potomac','A slave-trade ban and equal Senate seats','The Stamp Act and the Quebec Act','The Louisiana Purchase and the Embargo Act'],'The fiscal arrangement and capital location reconciled competing regional interests.','f','notes','slide 11');
add(8,'jeffersonvision','Jefferson’s vision','Which social ideal did Jefferson emphasize?', ['Independent farmers as the basis of a republic','A hereditary aristocracy of bankers','A nation with no western agriculture','An economy owned entirely by the British crown'],'He favored an agrarian republic and a more limited national government, while enslaving people himself.','pf','notes','slides 8–9');
add(8,'parties','First party system','Which pairing fits the first party system?', ['Federalists: Hamilton and Adams; Democratic-Republicans: Jefferson and Madison','Federalists: Jackson and Calhoun; Republicans: Penn and Williams','Federalists: Las Casas; Republicans: George III','Both parties had exactly the same views'],'Federalists generally favored stronger federal institutions and commerce; their rivals emphasized agrarian and state interests.','pf','notes','slides 12, 18');
add(8,'demreps','Democratic-Republicans','Who were the Democratic-Republicans of this period?', ['Jefferson and Madison’s opposition to the Federalists','The modern Republican Party founded in the 1850s','British royal judges','Only the supporters of Hamilton’s bank'],'The historical name “Republicans” refers to this early party, not today’s party.','kf','c8','P046');
add(8,'militia','Militia Act (1792)','What authority was important in the Militia Act of 1792?', ['The president could call state militias into federal service under specified conditions','The president could abolish every state at will','Militia service gave everyone equal citizenship','All standing forces were permanently outlawed'],'The laws set militia standards and mobilization authority. Eligibility reflected the period’s racial and gender exclusions.','pf','notes','slide 14');
add(8,'wabashtimbers','Wabash & Fallen Timbers','Which sequence describes the early frontier conflicts?', ['Native victory over St. Clair in 1791; Wayne’s victory at Fallen Timbers in 1794','US victory at every battle beginning in 1791','The French seized Ohio in 1795','The Treaty of Paris ended every frontier conflict'],'The 1795 Treaty of Greenville followed and forced major Native land cessions. Native resistance pursued independent interests.','f','notes','slide 13; C8P065');
add(8,'frenchrevolution','French Revolution & US politics','How did events in France affect US politics?', ['Initial enthusiasm became partisan division as revolutionary violence grew','Americans all joined the French army','Both parties stopped caring about foreign policy','It caused the Stamp Act in 1765'],'Federalists feared instability; Democratic-Republicans remained more sympathetic to France.','pf','notes','slides 16–18');
add(8,'terror','The Terror','What was the Terror during the French Revolution?', ['A period of revolutionary repression and executions','A British customs court in Boston','The US embargo on foreign trade','A peaceful exchange of cabinet offices'],'It intensified American arguments about revolution, liberty and order.','kf','c8','P053');
add(8,'neutrality','Neutrality (1793)','What policy did Washington adopt as Britain and France fought?', ['US neutrality','An automatic declaration of war on Britain','An immediate invasion of France','A ban on all political debate'],'The administration wanted to avoid war while the new nation remained weak.','f','c8','P054');
add(8,'genet','Citizen Genêt affair','What made Citizen Genêt’s activity controversial?', ['Recruiting privateers and seeking American support for France despite neutrality','Writing the Bill of Rights','Leading the British at New Orleans','Negotiating equal Senate representation'],'His efforts challenged Washington’s authority over foreign policy.','kf','c8','P055–056');
add(8,'marque','Letters of marque','What did a letter of marque authorize?', ['A privately owned vessel to attack an enemy’s shipping with government permission','A universal right to vote','The confiscation of every state’s land','The president to appoint a king'],'Licensed privateering differs from piracy without government authorization.','kf','c8','P055');
add(8,'impressment','Impressment','What was impressment?', ['Forcing sailors into naval service','A voluntary enlistment bonus','A tariff on imported cloth','A judicial veto'],'British impressment and interference with American shipping fueled resentment and war pressure.','kf','c8','P057');
add(8,'jay','Jay’s Treaty','What was a major limitation of Jay’s Treaty?', ['It did not end impressment, despite settling other disputes with Britain','It gave the US all of Canada','It made France a US state','It prohibited all British trade forever'],'British withdrawal from western posts was one achievement; critics believed too much had been conceded.','f','c8','P057');
add(8,'pinckney','Pinckney’s Treaty','What did Pinckney’s Treaty with Spain secure?', ['Mississippi navigation and the right of deposit at New Orleans','The sale of all Louisiana in 1795','US ownership of Canada','An end to the Quasi-War with France'],'Access mattered to western farmers moving products toward overseas markets.','f','c8','P058');
add(8,'haiti','Haiti & Louisiana','How did the Haitian Revolution affect Napoleon’s plans?', ['Resistance and disease undermined his Caribbean empire and helped encourage the Louisiana sale','It created the British national bank','It forced the US to abolish slavery in 1803','It gave France permanent control of all North America'],'Haiti became independent in 1804. The Louisiana Purchase followed a French imperial reversal, not an empty-continent sale.','f','notes','slides 37–40; C8P059–061');
add(8,'whiskey','Whiskey Rebellion (1794)','What did the Whiskey Rebellion test?', ['The federal government’s ability to enforce an excise tax','The Stamp Act’s enforcement in 1765','The Constitution’s nine-state ratification rule','Britain’s authority over Massachusetts'],'Washington mobilized a large militia force; most resistance collapsed before a major battle.','pf','notes','slides 19–20');
add(8,'shayswhiskey','Shays’s vs Whiskey Rebellion','What difference do the lecture notes emphasize?', ['State forces suppressed Shays’s; federal authority mobilized forces against the whiskey rebels','Both were suppressed by the same British army','Whiskey happened under the Articles in 1786','Shays’s happened during Jefferson’s presidency'],'The comparison illustrates the change from the Articles to a stronger constitutional government.','pf','notes','slide 20');
add(8,'farewell','Washington’s Farewell Address','What dangers did Washington warn about?', ['Sectional division, partisan conflict and entanglement with foreign powers','Every form of overseas commerce','All representative government','A two-house legislature'],'He urged union and caution about lasting foreign attachments, not a complete end to international contact.','f','notes','slides 21–22');
add(8,'election1796','Election of 1796','Why did Adams and Jefferson hold office together despite being rivals?', ['The original electoral system made the runner-up vice president','The modern primary system required a unity ticket','Jefferson was Adams’s chosen running mate','Congress abolished vice-presidential elections'],'Adams became president and Jefferson vice president. The system later changed with the Twelfth Amendment.','f','notes','slide 23');
add(8,'xyz','XYZ affair','What demand caused outrage in the XYZ affair?', ['French intermediaries demanded a bribe and loan before negotiations','Britain demanded the return of Louisiana','Spain requested Senate representation','Washington demanded monarchy'],'The 1797 diplomatic confrontation fueled anti-French feeling and an undeclared naval conflict.','pkf','xyz','slide 24; C8P070');
add(8,'quasiwar','Quasi-War (1798–1800)','What was the Quasi-War?', ['An undeclared naval conflict between the United States and France','The US invasion of Canada in 1812','A civil war between Virginia and New Jersey','The final battle of the Revolution'],'The Convention of 1800 ended the conflict. The handout’s 1796 start is a typo; the lecture’s 1798–1800 dates match the diplomatic record.','pf','xyz','slides 25, 29; C8P069');
add(8,'alien','Alien and Sedition Acts','Why were the Alien and Sedition Acts controversial?', ['They expanded action against foreigners and punished some criticism of the government','They guaranteed unrestricted criticism of every official','They ended all partisan disagreement','They granted citizenship to every immigrant immediately'],'Federalist measures in 1798 raised concerns about immigration, free speech and political repression.','pf','notes','slides 26–27');
add(8,'resolutions','Virginia & Kentucky Resolutions','Who helped write the Virginia and Kentucky Resolutions?', ['Madison for Virginia and Jefferson for Kentucky','Hamilton for both states','Washington and Franklin','Jackson and Clay'],'They challenged the Alien and Sedition Acts and advanced state-based constitutional resistance. Other states did not generally accept the claims.','pf','notes','slide 28');
add(8,'revolution1800','Revolution of 1800','Why is the election of 1800 called a revolution?', ['Power passed peacefully from Federalists to Democratic-Republicans','It replaced the Constitution with a king','It abolished elections for all future presidents','It ended slavery everywhere'],'Jefferson’s victory changed party control through constitutional procedures despite bitter conflict.','pkf','c8','P074; slide 30');
add(8,'tie1800','Jefferson–Burr tie','How was the 1800 tie between Jefferson and Burr resolved?', ['The House chose Jefferson after repeated ballots','The Supreme Court held a national popular election','Burr automatically became president','Washington returned for a third term'],'The House selected Jefferson on the thirty-sixth ballot. Electors had not cast separate ballots for the two offices.','f','notes','slide 30');
add(8,'twelfth','Twelfth Amendment','What did the Twelfth Amendment change?', ['Electors cast separate votes for president and vice president','Each state gained twelve senators','The Supreme Court became elected','All property qualifications ended'],'Ratified in 1804, it addressed problems exposed by the earlier electoral rules.','f','notes','slide 43');
add(8,'jeffersoncuts','Jefferson’s presidency','Which policy fit Jefferson’s limited-government program?', ['Reducing military spending and internal taxes while paying down debt','Restoring the Stamp Act','Abolishing every court','Ending all customs revenue'],'His policies still faced practical tensions, including naval war and the Louisiana Purchase.','f','notes','slide 32');
add(8,'marbury','Marbury v. Madison (1803)','What principle is associated with Marbury v. Madison?', ['Judicial review: courts can find laws unconstitutional','Congress can abolish the Constitution by ordinary vote','The president can ignore every court automatically','Judges must be chosen by a nationwide popular vote'],'Marshall’s Court held that the statutory expansion of its original jurisdiction conflicted with the Constitution. Marbury did not obtain the requested writ.','pkf','notes','slides 33–35; C8P080');
add(8,'louisiana','Louisiana Purchase','What did the Louisiana Purchase (1803) do?', ['Buy France’s Louisiana claim for $15 million and roughly double the nation’s claimed area','Buy Canada from Britain in 1812','Grant citizenship to every Indigenous resident immediately','End the Quasi-War in 1798'],'The purchase expanded US claims over Native homelands; it did not mean France owned every community’s land with their consent.','pkf','c8','P082; slide 36');
add(8,'purchasepower','Louisiana & strict construction','Why did the Louisiana Purchase create a dilemma for Jefferson?', ['The Constitution did not expressly authorize buying territory, challenging his narrow interpretation','It violated an explicit ban on every treaty','France refused any sale','Congress had already prohibited western settlement forever'],'He accepted the treaty route rather than waiting for an amendment, adapting principle to opportunity.','f','notes','slide 40');
add(8,'barbary','Barbary War','What led to the first Barbary War under Jefferson?', ['Conflict over tribute demanded for protection of American shipping','The Stamp Act tax on newspapers','A British invasion of Boston','A dispute over equal Senate seats'],'Tripoli declared war in 1801 after Jefferson resisted new demands. US naval operations continued through the 1805 settlement.','pf','notes','slides 41–42');
add(8,'embargo','Embargo Act (1807)','What did Jefferson hope the Embargo Act would achieve?', ['Use trade restrictions to pressure Britain and France without war','Increase American exports to every foreign port','Help Britain force sailors into its navy','Purchase Louisiana again'],'It blocked American overseas trade and caused severe harm to US merchants and producers, especially in port communities.','pf','notes','slides 44–48');
add(8,'chesapeake','Chesapeake–Leopard affair','Why did the Chesapeake–Leopard affair intensify resentment?', ['A British warship attacked an American vessel and removed sailors in 1807','France sold Louisiana for a higher price','Congress gave Britain two senators','The US surrendered Fort McHenry'],'The episode dramatized British interference with American shipping and helped prompt the embargo.','f','notes','slides 45–47');
add(8,'nonintercourse','Non-Intercourse Act (1809)','How did the Non-Intercourse Act change the embargo?', ['Reopened trade except with Britain and France','Banned trade with every country permanently','Ended the War of 1812','Gave France control of the American navy'],'It narrowed restrictions. The correct date is 1809; the edited chapter’s 1808 date is a typo.','f','c8','P091; slides 49–50');
add(8,'warhawks','War Hawks','What did War Hawks such as Henry Clay and John Calhoun urge?', ['War against Britain over maritime violations and frontier concerns','A return to the Articles','Peace at any cost with no military action','French annexation of the United States'],'Their influence helped press Madison toward war in 1812.','f','notes','slide 51');
add(8,'tecumseh','Tecumseh & Tenskwatawa','What did Tecumseh seek?', ['A Native confederacy resisting US expansion into Indigenous lands','The presidency of the United States','A British seat in Congress','A national bank in Washington'],'Tenskwatawa’s religious movement supported resistance. Native participants pursued their own goals, beyond serving British or US interests.','f','c8','P090–092');
add(8,'war1812','War of 1812','Which combination contributed to the War of 1812?', ['Impressment, trade interference and frontier conflict','The tea tax and the Stamp Act alone','A unanimous desire to annex France','The Virginia Plan and Senate representation'],'Madison signed the declaration in June 1812 after Congress approved war. Support and opposition differed by region and party.','pf','notes','slides 52–54');
add(8,'canada1812','Invasion of Canada','What did the early US invasions of Canada reveal?', ['Capturing Canada was far harder than some US leaders expected','Canada joined the US without resistance','Britain had no forces or allies there','Every US military campaign succeeded'],'Poor preparation and determined resistance contributed to American setbacks.','f','notes','slide 54');
add(8,'washington1814','Burning of Washington','When did British forces burn major public buildings in Washington?', ['August 1814','July 1776','September 1783','January 1803'],'The burning followed the American defeat at Bladensburg on August 24, 1814. The edited chapter’s July date is a typo.','pf','notes','slide 55; C8P096');
add(8,'mchenry','Fort McHenry','What did Fort McHenry’s defense accomplish in September 1814?', ['Helped prevent the capture of Baltimore and inspired Key’s poem','Ended the Revolution in 1781','Forced Britain to sell Canada','Destroyed the entire British fleet'],'Armistead’s garrison withstood bombardment on September 13–14. Francis Scott Key watched from outside the fort.','pf','mchenry','slide 56');
add(8,'orleans','Battle of New Orleans','Which statement about the Battle of New Orleans is accurate?', ['Jackson’s January 1815 victory came after Ghent was signed but before US ratification','It happened after the treaty had already taken effect in the US','It gave the US all of Canada','It was the first battle of the Revolution'],'News traveled slowly. The victory made Jackson a national figure; the treaty became effective in February 1815.','pf','ghent','slide 57; C8P099–100');
add(8,'ghent','Treaty of Ghent','What was the main territorial result of the Treaty of Ghent?', ['Restoration of prewar boundaries','The annexation of Canada by the US','The sale of Louisiana','A return of the US to British colonial rule'],'Signed December 24, 1814, the treaty largely restored the territorial status quo rather than awarding a conquest.','f','ghent','slide 58');
add(8,'hartford','Hartford Convention','How did the Hartford Convention damage the Federalists?', ['Wartime opposition looked disloyal after peace and the New Orleans victory','It elected a Federalist king','It unanimously declared every state independent','It forced Madison to surrender Baltimore'],'Delegates proposed constitutional changes. The party’s reputation suffered; discussion of secession was not the same as a formal unanimous secession vote.','pf','notes','slide 59');
add(8,'legacy1812','Legacy of the War of 1812','Which was a major result of the war’s aftermath?', ['Stronger US nationalism and a weakened Federalist Party','The immediate abolition of slavery','A permanent US occupation of Canada','The disappearance of Native resistance without further conflict'],'US expansion continued to threaten Native peoples. National celebration did not mean equal benefits for every group.','f','c8','P097–100');

add(7,'monarchy','Monarchy','What is a monarchy?', ['Government headed by a king or queen','Government without any executive','A legislature with two chambers','A federal division of powers'],'The hereditary British crown became the institution Patriots rejected in establishing a republic.','kf','c7','P007');
add(7,'majority','Majority rule','What does majority rule mean?', ['Decisions reflect the choice of more than half of the relevant voters','One ruler makes every decision alone','Only the smallest minority can decide','Every decision always requires unanimity'],'Constitutional limits and protected rights can restrain what a majority may lawfully do.','kf','c7','P009');
add(7,'conservative','Conservative Whigs','Which view fits conservative Whigs after independence?', ['Property-owning elites should lead to preserve order','Hereditary monarchy was the only valid government','Everyone should have equal political power immediately','Government should have no institutions'],'They supported a republic but feared excessive democracy and instability.','kf','c7','P009');
add(7,'radical','Radical Whigs','Which view fits radical Whigs?', ['Broader political participation and distrust of concentrated elite power','A permanent aristocracy should govern without elections','The king should appoint all state legislators','No ordinary person should have a political voice'],'Their approach was more democratic than conservative Whig leadership, though historical exclusions remained.','kf','c7','P010');
add(8,'billrights8','Bill of Rights','Which statement correctly describes the Bill of Rights?', ['The first ten amendments, ratified in 1791, limiting government and protecting liberties','The original Constitution’s first ten articles','A treaty signed with France in 1798','A list of Hamilton’s manufacturing subsidies'],'For example, the Third Amendment bars peacetime quartering without the owner’s consent; wartime quartering must follow law.','kf','rights','C8P010–030; slide 99');
add(8,'cabinet','Washington’s cabinet','Which pairing of cabinet officers is correct?', ['Hamilton: Treasury; Jefferson: State','Hamilton: State; Jefferson: Treasury','Adams: Chief Justice; Marshall: Vice President','Jackson: Treasury; Calhoun: State in 1789'],'Washington’s administration established precedents. Hamilton and Jefferson developed rival economic and constitutional visions.','f','notes','slide 4');
add(8,'tariffs','Tariffs & manufacturing','What did Hamilton’s manufacturing proposals favor?', ['Federal encouragement of industry through measures such as tariffs and proposed subsidies','A ban on every factory','Unrestricted dependence on British manufacturing','The end of all public revenue'],'His vision was not adopted in every detail. Distinguish proposed programs from what Congress actually enacted.','f','notes','slide 6; C8P042');
add(8,'citizenship','Citizenship’s limits','What limit did the Naturalization Act of 1790 impose?', ['Naturalization was restricted to free white persons meeting its requirements','It gave every foreign-born person immediate citizenship','It granted all women equal voting rights','It abolished slavery in the United States'],'The law concerned naturalization of immigrants; it should not be treated as a complete definition of all citizenship by birth.','','c8','P045');
add(7,'cincinnati','Society of the Cincinnati','Why did some critics distrust the Society of the Cincinnati?', ['Hereditary membership among officers seemed to resemble aristocratic privilege','It required every member to free all enslaved people','It abolished military leadership','It gave every farmer a national vote'],'Washington’s retirement evoked the citizen-soldier Cincinnatus, but hereditary privilege raised republican concerns.','','c7','P011–013');
add(7,'senators','Original selection of senators','How were US senators originally selected?', ['By state legislatures','By the president alone','By the British Parliament','By the Supreme Court'],'The Seventeenth Amendment introduced direct election much later. This differs from the original Constitution’s system.','','constitution','Article I §3');
